    adcs_vec3_t h_sum = {0.0, 0.0, 0.0};
    adcs_vec3_t tau_body_sum = {0.0, 0.0, 0.0};
    double P_mech = 0.0;
    double P_bus = 0.0;
    size_t i;
    adcs_vec3_t axis_norm;
    double J, omega, u, p_inst;

    if ((wheels == NULL) || (wheel_torque == NULL) || (momentum == NULL) || 
        (body_torque == NULL) || (mechanical_power == NULL) || (bus_power == NULL)) {
        return ADCS_E_NULL;
    }

    if ((count < 1) || (count > 16) || (!isfinite(efficiency)) || (efficiency <= 0.0) || (efficiency > 1.0)) {
        return ADCS_E_RANGE;
    }

    for (i = 0; i < count; i++) {
        const adcs_wheel_t *w = &wheels[i];
        double torque_val = wheel_torque[i];

        if ((!isfinite(w->inertia_kg_m2)) || (!isfinite(w->speed_rad_s)) || 
            (!isfinite(torque_val))) {
            return ADCS_E_RANGE;
        }

        if (adcs_vec3_normalize(&w->axis_body, ADCS_EPS_NORM, &axis_norm) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        J = w->inertia_kg_m2;
        omega = w->speed_rad_s;
        u = torque_val;

        h_sum.x += J * omega * axis_norm.x;
        h_sum.y += J * omega * axis_norm.y;
        h_sum.z += J * omega * axis_norm.z;

        tau_body_sum.x -= u * axis_norm.x;
        tau_body_sum.y -= u * axis_norm.y;
        tau_body_sum.z -= u * axis_norm.z;

        p_inst = u * omega;
        P_mech += p_inst;

        if (p_inst > 0.0) {
            P_bus += p_inst / efficiency;
        }
    }

    *momentum = h_sum;
    *body_torque = tau_body_sum;
    *mechanical_power = P_mech;
    *bus_power = P_bus;

    return ADCS_OK;
}

