    if ((wheels == NULL) || (wheel_torque == NULL) || (momentum == NULL) ||
        (body_torque == NULL) || (mechanical_power == NULL) || (bus_power == NULL)) {
        return ADCS_E_NULL;
    }

    if (count < 1 || count > 16 || !isfinite(efficiency) || efficiency <= 0.0 || efficiency > 1.0) {
        return ADCS_E_RANGE;
    }

    adcs_status_t status = adcs_wheel_momentum(wheels, count, momentum);
    if (status != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    *body_torque = (adcs_vec3_t){0.0, 0.0, 0.0};
    *mechanical_power = 0.0;
    *bus_power = 0.0;

    for (size_t i = 0; i < count; ++i) {
        if (!isfinite(wheel_torque[i])) {
            return ADCS_E_RANGE;
        }

        adcs_vec3_t normalized_axis;
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &normalized_axis) != ADCS_OK) {
            return ADCS_E_RANGE;
        }

        double torque = wheel_torque[i];
        double speed = wheels[i].speed_rad_s;

        // tau_body = -sum(u_i * a_i)
        adcs_vec3_t torque_vec = adcs_vec3_scale(&normalized_axis, torque);
        *body_torque = adcs_vec3_sub(body_torque, &torque_vec);

        // P_mech = sum(u_i * omega_i)
        *mechanical_power += torque * speed;

        // P_bus = sum_{u_i*omega_i>0}(u_i*omega_i/efficiency)
        double p_inst = torque * speed;
        if (p_inst > 0.0) {
            *bus_power += p_inst / efficiency;
        }
    }

    return ADCS_OK;
}

